---@class ParkourBuff.Magnet:ParkourBuff.Buff
local Magnet = Class("Magnet", import("Game.Activity.ParkourGame.MainGame.Buff.Buff"))

local CriWareUtils = import('Game.Entry.CriWareUtilsFix')


function Magnet:__init(duration, range)
    self.super.__init(self)
    self.duration = duration
    self.range = range
end

function Magnet:Type()
    return "Magnet"
end

function Magnet:OnStart()
    self.super.OnStart(self)
    self.trackSegments = self.Mgr.gameRunner:GetInteractionTrackSegments()
    self.playerTransform = self.player.controller.transform
    self.player:SetRoleFX( "fx_role_magnet", true, false, true ) 
    CriWareUtils.PlaySe( "Audio/sfx_instance_miniworld_parkour", "cat_magnet_12001801" )
end

function Magnet:OnTick(deltaTime)
    --local numFound = Physics.OverlapSphereNonAlloc(self.controller.transform.position, GrounTestDistance, self.colliders, 15, QueryTriggerInteraction.Ignore)
    --for i = 0, numFound - 1 do
    --    local collider = self.colliders[i]
    --end
    self.duration = self.duration - deltaTime
    if self.duration < 0 then
        self.alive = false
    end

    if self.alive then
        for i = 1, #self.trackSegments do
            local trackSegment = self.trackSegments[i]
            if trackSegment then
                local items = trackSegment.items
                for j = 1, #items do
                    local item = items[j]
                    local itemGo = item.controller.gameObject
                    local itemTF = itemGo.transform

                    if isNull(itemGo) then 
                        printError("吸铁石 吸到异常 item")
                    else
                        if item.Type() >= self.ParkourGameUtil.TrackItemType.Coin and itemGo.activeSelf then
                            local playerPos = Vector3.Covert(self.playerTransform.position)
                            local itemPos = Vector3.Covert(itemTF.position)
                            local distance = Vector3.Distance(playerPos, itemPos)
                            if distance < self.range then
                                itemTF.position = Vector3.MoveTowards(itemPos, playerPos, 20 * deltaTime)
                            end
                        else 
                            --printError("没吸到: " .. tostring(itemGo.name) .. ", activeSelf = " .. tostring(itemGo.activeSelf) .. ", type = " .. tostring(item.Type()) )
                        end
                    end 
                end
            end
        end
    end
end

function Magnet:AddSameBuff(buff)
    self.duration = self.duration + buff.duration
end


function Magnet:OnEnd()
    self.super.OnEnd(self)
    self.player:SetRoleFX( "fx_role_magnet", false, false, true ) 
    CriWareUtils.Stop( "Audio/sfx_instance_miniworld_parkour", "cat_magnet_12001801" )
end


return Magnet